        x=float(parts[0].replace(',','.'))
        y=float(parts[1].replace(',','.'))
        xs.append(x); ys.append(y)

# sort ascending
sorted_xy=sorted(zip(xs,ys), key=lambda t:t[0])
xs=[x for x,y in sorted_xy]; ys=[y for x,y in sorted_xy]

# function to estimate parameters

def estimate_peak(lo,hi,edge_frac=0.15):
    # extract range
    xs_r=[x for x in xs if lo<=x<=hi]
    ys_r=[y for x,y in zip(xs,ys) if lo<=x<=hi]
    n=len(xs_r)
    if n<5:
        raise ValueError('not enough points')
    # find max
    max_idx=max(range(n), key=lambda i: ys_r[i])
    x0=xs_r[max_idx]; max_y=ys_r[max_idx]
    # baseline from edges: take lowest 20% y? or edges by x? We'll use edges by x.
    edge_n=max(3, int(n*edge_frac))
    edge_vals=ys_r[:edge_n]+ys_r[-edge_n:]
    offset=statistics.median(edge_vals)
    amplitude=max_y - offset
    half=offset + amplitude/2
    # find left crossing
    left_x=None; right_x=None
    # left: go from max_idx downwards to find first y<=half
    for i in range(max_idx,0,-1):
        y1=ys_r[i]; y0=ys_r[i-1];
        if (y1>=half and y0<=half) or (y1<=half and y0>=half):
            # interpolate between i-1 and i
            x1=xs_r[i]; x0i=xs_r[i-1]
            if y1==y0:
                left_x=x0i
            else:
                t=(half-y0)/(y1-y0)
                left_x=x0i + t*(x1-x0i)
            break
    # right crossing
    for i in range(max_idx,n-1):
        y1=ys_r[i]; y2=ys_r[i+1]
        if (y1>=half and y2<=half) or (y1<=half and y2>=half):
            x1=xs_r[i]; x2=xs_r[i+1]
            if y2==y1:
                right_x=x2
            else:
                t=(half-y1)/(y2-y1)
                right_x=x1 + t*(x2-x1)
            break
    if left_x is None or right_x is None:
        # fallback: use width to 10%? just approximate using range
        left_x=xs_r[0]; right_x=xs_r[-1]
    gamma=(right_x-left_x)/2
    return dict(x0=x0,gamma=gamma,amplitude=amplitude,offset=offset, max_y=max_y, half=half, left_x=left_x, right_x=right_x, n=n)

for name,(lo,hi) in [('G',(1580-120,1580+120)), ('2D',(2700-250,2700+250))]:
