sorted_xy=sorted(zip(xs,ys), key=lambda t:t[0])
xs=[x for x,y in sorted_xy]; ys=[y for x,y in sorted_xy]

# smoothing

def smooth(y, window=7):
    n=len(y)
    if window<3:
        return y[:]
    half=window//2
    out=[]
    for i in range(n):
        s=0; c=0
        for j in range(i-half, i+half+1):
            if 0<=j<n:
                s+=y[j]; c+=1
        out.append(s/c)
    return out


def estimate_initial(xs_r, ys_r):
    n=len(xs_r)
    ys_s=smooth(ys_r, window=9)
    max_idx=max(range(n), key=lambda i: ys_s[i])
    x0=xs_r[max_idx]; max_y=ys_s[max_idx]
    edge_n=max(3, int(n*0.1))
    edge_vals=ys_r[:edge_n]+ys_r[-edge_n:]
    offset=statistics.median(edge_vals)
    amplitude=max_y - offset
    # half max
    half=offset + amplitude/2
    left=None; right=None
    for i in range(max_idx,0,-1):
        y1=ys_s[i]; y0=ys_s[i-1]
        if (y1>=half and y0<=half) or (y1<=half and y0>=half):
            x1=xs_r[i]; x0i=xs_r[i-1]
            if y1==y0:
                left=x0i
            else:
                t=(half-y0)/(y1-y0)
                left=x0i + t*(x1-x0i)
            break
    for i in range(max_idx,n-1):
        y1=ys_s[i]; y2=ys_s[i+1]
        if (y1>=half and y2<=half) or (y1<=half and y2>=half):
            x1=xs_r[i]; x2=xs_r[i+1]
            if y2==y1:
                right=x2
            else:
                t=(half-y1)/(y2-y1)
                right=x1 + t*(x2-x1)
            break
    if left is None or right is None:
        left=xs_r[0]; right=xs_r[-1]
    gamma=max((right-left)/2, 1e-3)
    return x0, gamma, amplitude, offset


def sse(params, xs_r, ys_r):
    x0,gamma,amp,offset=params
    if gamma<=0 or amp<0:
        return 1e99
    g2=gamma*gamma
    err=0.0
    for x,y in zip(xs_r,ys_r):
        model=offset + amp * g2 / ((x-x0)**2 + g2)
        diff=y-model
        err += diff*diff
    return err


def fit_peak(lo,hi):
    xs_r=[x for x in xs if lo<=x<=hi]
    ys_r=[y for x,y in zip(xs,ys) if lo<=x<=hi]
    if len(xs_r)<5:
        raise ValueError('not enough data')
    # start
    x0,gamma,amp,offset=estimate_initial(xs_r, ys_r)
    params=[x0,gamma,amp,offset]
    best=sse(params,xs_r,ys_r)
    step=[(hi-lo)*0.02, gamma*0.5 if gamma>0 else 1.0, max(abs(amp)*0.2,1.0), max(abs(amp)*0.2,1.0)]
    for iteration in range(250):
        improved=False
        # dynamic step adapt: try also smaller step for x0 and gamma each iteration
        for i in range(4):
            for sign in (-1,1):
                cand=params.copy()
                cand[i]+=sign*step[i]
                if i==1 and cand[i]<=1e-6:
                    continue
