                if err<best:
                    best=err; params=cand; improved=True
        if not improved:
            step=[s*0.6 for s in step]
            if max(step) < 1e-5:
                break
    return params, best

for name,(lo,hi) in [('G',(1600,1700)), ('2D',(2400,2800)), ('2D2',(2200,3000)), ('2D3',(2550,2850))]:
